mapper.select:
select c.id, c.tenant_id, c.model_id, m.model_name, m.provider_code, m.logo_path from ai_model_connection c join ai_model m on m.id = c.model_id where c.del_flag = 0 and c.data_status = #{enabled} and m.del_flag = 0 and m.data_status = #{enabled} and m.model_type = #{modelType}
and m.model_name ilike concat('%', #{keyword}, '%')
order by c.create_time desc, c.id desc


where c.del_flag = 0

    and c.model_id = #{modelId}


    and c.data_status = #{dataStatus}


    and m.provider_code = #{providerCode}

order by c.create_time desc, c.id desc
